import numpy as np
D=np.load('/app/output/start_depth_head_camera.npy').squeeze().astype(float)/1000
R=np.array([[1,0,0],[0,-.8,-.6],[0,.6,-.8]],float); t=np.array([.032,.45,1.35])
K=np.array([[358.642,0,160],[0,358.642,120],[0,0,1]])
Ri=np.linalg.inv(R); Ki=np.linalg.inv(K)
for name,(x1,x2,y1,y2) in {'water':(65,98,80,120),'coke':(208,244,40,100),'yellow':(265,300,0,75)}.items():
 pts=[]
 for y in range(y1,y2):
  for x in range(x1,x2):
   d=D[y,x]
   if not np.isfinite(d) or d<.2 or d>1.5: continue
   p=Ki@np.array([x,y,1.])*d
   w=Ri@(p-t)
   if .735<w[2]<.95: pts.append((x,y,*w))
 arr=np.array(pts)
 print('\n',name,'N',len(arr))
 if len(arr):
  print('mean x/y/z',arr[:,2:].mean(axis=0),'median',np.median(arr[:,2:],axis=0),'z q',np.quantile(arr[:,4],[0,.1,.5,.9,1]))
  for y in range(y1,y2,10):
   p=[]
   for x in range(x1,x2,5):
    d=D[y,x]; world=Ri@(Ki@np.array([x,y,1.])*d-t)
    if .735<world[2]<.96:p.append((x,round(world[0],3),round(world[1],3),round(world[2],3)))
   print(y,p)
